import json
from itertools import permutations

def solve_puzzle():
    # Input variables
    houses = [1, 2, 3, 4]
    names = ["Alice", "Arnold", "Peter", "Eric"]
    hairs = ["black", "blonde", "brown", "red"]

    solutions = []

    for name_perm in permutations(names):
        pos_name = {name: idx + 1 for idx, name in enumerate(name_perm)}

        # Clue 5: Alice is in the first house.
        if pos_name["Alice"] != 1:
            continue

        # Clue 2: Alice and Arnold are next to each other.
        if abs(pos_name["Alice"] - pos_name["Arnold"]) != 1:
            continue

        # Clue 1 implies Eric cannot be in the last house (must have someone to the right).
        if pos_name["Eric"] == 4:
            continue

        for hair_perm in permutations(hairs):
            hair_at = {house: hair_perm[house - 1] for house in houses}

            # Clue 4: The person who has black hair is not in the first house.
            if hair_at[1] == "black":
                continue

            # Clue 3: Eric is the person who has brown hair.
            if hair_at[pos_name["Eric"]] != "brown":
                continue

            # Clue 1: Eric is directly left of the person who has blonde hair.
            if pos_name["Eric"] + 1 > 4:
                continue
            if hair_at[pos_name["Eric"] + 1] != "blonde":
                continue

            # Construct solution rows
            rows = []
            for house in houses:
                rows.append([str(house), name_perm[house - 1], hair_at[house]])
            solutions.append(rows)

    # Expect exactly one solution
    if not solutions:
        raise ValueError("No solution found.")
    if len(solutions) > 1:
        # If multiple solutions exist, choose the first to conform to the required output format
        rows = solutions[0]
    else:
        rows = solutions[0]

    output = {
        "solution": {
            "header": ["House", "Name", "Hair"],
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
